PTX_SOURCE = r"""
.version 7.1
.target sm_80
.address_size 64

.visible .entry maxpool1d_kernel(
    .param .u64   input_ptr,          // pointer to fp16 input tensor
    .param .u64   output_ptr,         // pointer to fp16 output tensor
    .param .u32   batch,              // batch size
    .param .u32   features,           // number of channels
    .param .u32   seq_len,            // input sequence length
    .param .u32   out_len,            // output sequence length
    .param .u32   kernel_size,        // pooling window size
    .param .u32   stride,             // stride
    .param .u32   padding,            // left/right padding
    .param .u32   dilation            // dilation
)
{
    // -------------------------------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------------------------------
    .reg .u64   in_ptr, out_ptr;
    .reg .u32   B, C, L, O, K, S, P, D;
    .reg .u32   tid, total, blockDimX, blockIdxX, threadIdxX;

    ld.param.u64   in_ptr,   [input_ptr];
    ld.param.u64   out_ptr,  [output_ptr];
    ld.param.u32   B,        [batch];
    ld.param.u32   C,        [features];
    ld.param.u32   L,        [seq_len];
    ld.param.u32   O,        [out_len];
    ld.param.u32   K,        [kernel_size];
    ld.param.u32   S,        [stride];
    ld.param.u32   P,        [padding];
    ld.param.u32   D,        [dilation];

    // -------------------------------------------------------------------------
    // Compute linear thread id
    // -------------------------------------------------------------------------
    mov.u32   %r1, %tid.x;      // threadIdx.x
    mov.u32   %r2, %ctaid.x;    // blockIdx.x
    mov.u32   %r3, %ntid.x;     // blockDim.x
    mul.lo.u32 %r2, %r2, %r3;   // blockIdx.x * blockDim.x
    add.u32   %r1, %r1, %r2;    // global thread id
    mov.u32   tid, %r1;

    // total = B * C * O
    mul.lo.u32 %r4, B, C;
    mul.lo.u32 total, %r4, O;

    // -------------------------------------------------------------------------
    // Main loop – each thread may process several output elements
    // -------------------------------------------------------------------------
    @! (tid < total) bra DONE;

MAIN_LOOP:
    // ---------------------------------------------------------------------
    // De‑compose linear index into (batch, channel, out_pos)
    // ---------------------------------------------------------------------
    .reg .u32 q1, r1, q2, r2, out_pos, channel, batch_idx;

    // q1 = tid / O ; out_pos = tid % O
    div.u32   q1, tid, O;
    mul.lo.u32 %r5, q1, O;
    sub.u32   out_pos, tid, %r5;

    // q2 = q1 / C ; channel = q1 % C
    div.u32   q2, q1, C;
    mul.lo.u32 %r6, q2, C;
    sub.u32   channel, q1, %r6;

    // batch_idx = q2
    mov.u32   batch_idx, q2;

    // ---------------------------------------------------------------------
    // Compute start index of the pooling window (signed)
    // ---------------------------------------------------------------------
    .reg .s32 start, idx, k;
    cvt.s32.u32   start, out_pos;
    mul.lo.s32    start, start, S;          // out_pos * stride
    sub.s32       start, start, P;          // - padding

    // ---------------------------------------------------------------------
    // Initialise max value to the smallest possible fp16 number
    // ---------------------------------------------------------------------
    .reg .f16   max_val, cur_val;
    mov.f16    max_val, -65504.0;           // -max finite FP16

    // ---------------------------------------------------------------------
    // Loop over kernel elements
    // ---------------------------------------------------------------------
    mov.s32    k, 0;
K_LOOP:
    setp.ge.u32  %p1, k, K;
    @%p1 bra END_K_LOOP;

    // idx = start + k * dilation
    mul.lo.s32   %r7, k, D;
    add.s32      idx, start, %r7;

    // Bounds check: 0 <= idx < L
    setp.ge.s32  %p2, idx, 0;        // idx >= 0
    @!%p2 bra SKIP_LOAD;            // negative -> skip
    setp.lt.s32  %p3, idx, L;        // idx < L
    @!%p3 bra SKIP_LOAD;            // out of range -> skip

    // Linear address of input element
    // address = ((batch_idx * C + channel) * L + idx) * sizeof(half)
    .reg .u64 addr;
    mul.lo.u32   %r8, batch_idx, C;
    add.u32      %r9, %r8, channel;          // (batch*C + channel)
    mul.lo.u32   %r10, %r9, L;                // * L
    add.u32      %r11, %r10, idx;             // + idx
    cvt.u64.u32  %r12, %r11;
    mul.wide.u64 %r13, %r12, 2;               // half = 2 bytes
    add.u64      addr, in_ptr, %r13;

    // Load fp16 value
    ld.global.f16  cur_val, [addr];

    // max = max(max, cur_val)
    setp.gt.f16   %p4, cur_val, max_val;
    @%p4 mov.f16 max_val, cur_val;

SKIP_LOAD:
    add.s32   k, k, 1;
    bra      K_LOOP;

END_K_LOOP:
    // ---------------------------------------------------------------------
    // Store the result
    // ---------------------------------------------------------------------
    // out_addr = ((batch_idx * C + channel) * O + out_pos) * sizeof(half)
    mul.lo.u32   %r14, batch_idx, C;
    add.u32      %r15, %r14, channel;          // (batch*C + channel)
    mul.lo.u32   %r16, %r15, O;                // * O
    add.u32      %r17, %r16, out_pos;          // + out_pos
    cvt.u64.u32  %r18, %r17;
    mul.wide.u64 %r19, %r18, 2;                // half size
    add.u64      %r20, out_ptr, %r19;
    st.global.f16 [ %r20 ], max_val;

    // ---------------------------------------------------------------------
    // Next element handled by this thread
    // ---------------------------------------------------------------------
    add.u32   tid, tid, %ntid.x * %gridDim.x;   // stride over whole grid
    setp.lt.u32 %p5, tid, total;
    @%p5 bra MAIN_LOOP;

DONE:
    ret;
}
"""

