# Python wrapper that loads the PTX and launches the kernel
# -------------------------------------------------------------------------
class ModelNew:
    def __init__(self, kernel_size, stride, padding, dilation, return_indices):
        # PTX parameters are passed at launch time; we just store them
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation
        self.return_indices = return_indices  # unused – always False
        # Load PTX module via the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        # x is expected to be a CUDA tensor of dtype float16
        assert x.is_cuda and x.dtype == torch.float16
        B, C, L = x.shape
        K = self.kernel_size
        S = self.stride
        P = self.padding
        D = self.dilation

        # Compute output length using PyTorch’s formula
        O = (L + 2 * P - D * (K - 1) - 1) // S + 1

        out = torch.empty((B, C, O), dtype=torch.float16, device='cuda')

        # Launch configuration
        threads_per_block = 256
        total_elements = B * C * O
        blocks = (total_elements + threads_per_block - 1) // threads_per_block

        # Arguments need to be passed as Python ints / pointers
        args = [
            x.data_ptr(),                # input_ptr  (u64)
            out.data_ptr(),              # output_ptr (u64)
            B, C, L, O,                  # dimensions (u32)
            K, S, P, D                   # pooling parameters (u32)
        ]

        # Launch the kernel
        ptx_launch(
            self.module,
            "maxpool1d_kernel",
            grid=(blocks, 1, 1),
            block=(threads_per_block, 1, 1),
            args=args
        )
        return out
